   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_medium(state, eps, eps_inf, lam, eps_solute, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> High-frequency permittivity of the solvent
      real(wp), intent(in) :: eps_inf
      !> Correlation length of the solvent polarization
      real(wp), intent(in) :: lam
      !> Relative permittivity inside the cavity
      real(wp), intent(in) :: eps_solute
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp44, tmp66, tmp67, tmp68
      integer :: i, j

      if (state%matrix_free) then
         call nonlocal_pcm_point_mf_medium(state, eps, eps_inf, lam, eps_solute, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, &
                          "[nonlocal_pcm_point_medium] call nonlocal_pcm_point_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => lam)
      end associate

      state%eps_inf = eps_inf
      state%eps = eps
      state%eps_solute = eps_solute
      state%op1%npt = 3*npt
      state%op1%npoint = npt
      state%op1%id = 1
      state%op1%points => state%r
      state%s7 = 1.0_wp/lam
      state%s8 = 1.0_wp/state%eps_inf
      state%s9 = state%s8*state%eps
      state%s10 = sqrt(state%s9)
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, &
                        tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, &
                        tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, &
                        tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, &
                        tmp43

            do i = 1, j - 1
               tmp1 = -state%s2(j)
               tmp2 = state%s2(i) + tmp1
               tmp3 = state%s1(j)*tmp2
               tmp4 = -state%s3(j)
               tmp5 = state%s3(i) + tmp4
               tmp6 = tmp5*state%s4(j)
               tmp7 = tmp3 + tmp6
               tmp8 = -state%s5(j)
               tmp9 = state%s5(i) + tmp8
               tmp10 = tmp9*state%s6(j)
               tmp11 = tmp7 + tmp10
               tmp12 = tmp2**(2)
               tmp13 = tmp5**(2)
               tmp14 = tmp12 + tmp13
               tmp15 = tmp9**(2)
               tmp16 = tmp14 + tmp15
               tmp17 = 1.0_wp/sqrt(tmp16)
               tmp18 = tmp17**(3)
               tmp19 = tmp11*tmp18
               tmp20 = sqrt(tmp16)
               tmp21 = state%s7*tmp20
               tmp22 = tmp21*state%s10
               tmp23 = -tmp22
               tmp24 = exp(tmp23)
               tmp25 = 1.0_wp + tmp22
               tmp26 = tmp24*tmp25
               tmp27 = -tmp26
               tmp28 = 1.0_wp + tmp27
               tmp29 = tmp19*tmp28
               tmp30 = tmp29*state%a(j)
               tmp31 = -tmp30
               state%s11(i, j) = tmp31
               tmp32 = -tmp2
               tmp33 = state%s1(i)*tmp32
               tmp34 = -tmp5
               tmp35 = tmp34*state%s4(i)
               tmp36 = tmp33 + tmp35
               tmp37 = -tmp9
               tmp38 = tmp37*state%s6(i)
               tmp39 = tmp36 + tmp38
               tmp40 = tmp39*tmp18
               tmp41 = tmp40*tmp28
               tmp42 = tmp41*state%a(i)
               tmp43 = -tmp42
               state%s11(j, i) = tmp43
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         state%s11(i, i) = 0.0_wp
      end do
      state%op1%c1 => state%s11
      state%op1%c2 => state%s12
      state%s13 = 1.0_wp/state%eps
      tmp44 = -state%s13
      state%s14 = state%s8 + tmp44
      state%s15 = state%eps_solute*state%s14
      state%op1%c3 = state%s15
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                        tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, &
                        tmp65

            do i = 1, j - 1
               tmp45 = -state%s2(j)
               tmp46 = state%s2(i) + tmp45
               tmp47 = tmp46**(2)
               tmp48 = -state%s3(j)
               tmp49 = state%s3(i) + tmp48
               tmp50 = tmp49**(2)
               tmp51 = tmp47 + tmp50
               tmp52 = -state%s5(j)
               tmp53 = state%s5(i) + tmp52
               tmp54 = tmp53**(2)
               tmp55 = tmp51 + tmp54
               tmp56 = sqrt(tmp55)
               tmp57 = state%s7*tmp56
               tmp58 = tmp57*state%s10
               tmp59 = -tmp58
               tmp60 = exp(tmp59)
               tmp61 = tmp60 - 1.0_wp
               tmp62 = 1.0_wp/sqrt(tmp55)
               tmp63 = tmp61*tmp62
               tmp64 = tmp63*state%a(j)
               state%s16(i, j) = tmp64
               tmp65 = tmp63*state%a(i)
               state%s16(j, i) = tmp65
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp66 = state%s7*state%a(i)
         tmp67 = tmp66*state%s10
         tmp68 = -tmp67
         state%s16(i, i) = tmp68
      end do
      state%op1%c4 => state%s16
      state%s17 = state%s8*state%eps_solute
      state%op1%c5 = state%s17
      state%op1%c6 => state%s18
      state%s19 = state%s13*state%eps_inf
      state%op1%c7 = state%s19
      call state%solver%setup(state%op1, error)
      if (allocated(error)) return
      state%s20 = -state%s19
      state%s21 = 1.0_wp + state%s20
      state%s23 = -state%s15
      state%s25 = -state%s17
      state%s26 = 1.0_wp + state%s25
      state%s31 = 25.132741228718345_wp*state%eps_solute
      state%s32 = 1.0_wp/state%s31
      state%s34 = -state%s32
      state%s58 = lam**(-2)

      state%ready = 2
   end subroutine nonlocal_pcm_point_medium

   !> Nonlocal PCM (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs nonlocal_pcm_point_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] u  interior potential trace, times 4 pi
   !> @param[out] q  interior normal-field trace, times 4 pi
   !> @param[out] w_ext  exterior auxiliary trace, times 4 pi
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_solve(state, v, vn, energy, u, q, w_ext, grad_v, grad_vn, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      real(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Interior potential trace, times 4 pi
      real(wp), contiguous, intent(out) :: u(:)
      !> Interior normal-field trace, times 4 pi
      real(wp), contiguous, intent(out) :: q(:)
      !> Exterior auxiliary trace, times 4 pi
      real(wp), contiguous, intent(out) :: w_ext(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      real(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp8(:), tmp10(:), &
                               tmp13(:), tmp14(:), tmp16(:), tmp17(:), tmp18(:), tmp19(:), &
                               tmp20(:), tmp21(:), tmp22(:), tmp23(:), tmp24(:), tmp25(:), &
                               tmp26(:), tmp27(:), tmp28(:), tmp29(:), tmp30(:), tmp31(:), &
                               tmp32(:), tmp33(:), tmp34(:), tmp35(:), tmp36(:), tmp37(:), &
                               tmp38(:), tmp39(:), tmp40(:), tmp41(:), tmp43(:), tmp44(:), &
                               tmp45(:), tmp46(:), tmp49(:), tmp50(:), tmp51(:), tmp52(:), &
                               tmp53(:), tmp54(:), tmp55(:), tmp56(:), tmp57(:), tmp58(:)
      real(wp), allocatable :: tmp6(:), tmp7(:), tmp15(:)
      real(wp) :: tmp9, tmp11, tmp12, tmp42, tmp47, tmp48, tmp59, tmp60

      if (state%matrix_free) then
         call nonlocal_pcm_point_mf_solve(state, v, vn, energy, u, q, w_ext, grad_v, grad_vn, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] call nonlocal_pcm_point_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] vn: wrong shape")
         return
      end if
      if (any(shape(u) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] u: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] q: wrong shape")
         return
      end if
      if (any(shape(w_ext) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] w_ext: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp34(npt), stat=stat)
      if (stat == 0) allocate (tmp35(npt), stat=stat)
      if (stat == 0) allocate (tmp36(npt), stat=stat)
      if (stat == 0) allocate (tmp37(npt), stat=stat)
      if (stat == 0) allocate (tmp38(npt), stat=stat)
      if (stat == 0) allocate (tmp39(npt), stat=stat)
      if (stat == 0) allocate (tmp40(npt), stat=stat)
      if (stat == 0) allocate (tmp41(npt), stat=stat)
      if (stat == 0) allocate (tmp43(npt), stat=stat)
      if (stat == 0) allocate (tmp44(npt), stat=stat)
      if (stat == 0) allocate (tmp45(npt), stat=stat)
      if (stat == 0) allocate (tmp46(npt), stat=stat)
      if (stat == 0) allocate (tmp49(npt), stat=stat)
      if (stat == 0) allocate (tmp50(npt), stat=stat)
      if (stat == 0) allocate (tmp51(npt), stat=stat)
      if (stat == 0) allocate (tmp52(npt), stat=stat)
      if (stat == 0) allocate (tmp53(npt), stat=stat)
      if (stat == 0) allocate (tmp54(npt), stat=stat)
      if (stat == 0) allocate (tmp55(npt), stat=stat)
      if (stat == 0) allocate (tmp56(npt), stat=stat)
      if (stat == 0) allocate (tmp57(npt), stat=stat)
      if (stat == 0) allocate (tmp58(npt), stat=stat)
      if (stat == 0) allocate (tmp6(3*npt), stat=stat)
      if (stat == 0) allocate (tmp7(3*npt), stat=stat)
      if (stat == 0) allocate (tmp15(3*npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op1%points => state%r
      state%op1%c1 => state%s11
      state%op1%c2 => state%s12
      state%op1%c4 => state%s16
      state%op1%c6 => state%s18
      state%v = v
      state%vn = vn
      call gemv(state%s11, state%v, state%s22)
      call gemv(state%s16, state%vn, state%s24)
      call gemv(state%s18, state%vn, state%s27)
      tmp1 = state%s21*state%s22
      tmp2 = state%s23*state%s24
      tmp3 = tmp1 + tmp2
      tmp4 = state%s26*state%s27
      tmp5 = tmp3 + tmp4
      tmp6(1:npt) = tmp5
      tmp6(npt + 1:2*npt) = 0.0_wp
      tmp6(2*npt + 1:3*npt) = tmp4
      tmp7 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp6, tmp7, error)
      if (allocated(error)) return
      state%s28 = tmp7(npt + 1:2*npt)
      state%s29 = tmp7(1:npt)
      tmp8 = state%a*state%s28
      tmp9 = dot(tmp8, state%v)
      tmp10 = state%a*state%s29
      tmp11 = dot(tmp10, state%vn)
      tmp12 = -tmp11
      state%s30 = tmp9 + tmp12
      state%s33 = tmp7(2*npt + 1:3*npt)
      state%s35 = state%s34*state%vn
      state%s36 = state%s32*state%v
      tmp13 = state%s35*state%a
      tmp14 = state%s36*state%a
      tmp15(1:npt) = tmp13
      tmp15(npt + 1:2*npt) = tmp14
      tmp15(2*npt + 1:3*npt) = 0.0_wp
      call state%solver%solve(state%op1, .true., tmp15, state%s37, error)
      if (allocated(error)) return
      state%s38 = state%s37(1:npt)
      state%s39 = state%s21*state%s38
      state%s40 = state%s37(2*npt + 1:3*npt)
      state%s41 = state%s40 + state%s38
      state%s42 = state%s26*state%s41
      state%s43 = state%s23*state%s38
      state%s45 = -state%s40
      state%s46 = -state%s38
      state%s47 = state%s45 + state%s46
      state%s49 = state%vn + state%s28
      state%s51 = state%s20*state%s38
      energy = state%s30*state%s32
      u = state%s29
      q = state%s28
      tmp16 = state%s26*state%v
      w_ext = state%s33 + tmp16
      tmp17 = state%s32*tmp8
      call gemv(state%s11, state%s39, tmp18, trans="t")
      grad_v = tmp17 + tmp18
      tmp19 = state%s34*tmp10
      call gemv(state%s18, state%s42, tmp20, trans="t")
      tmp21 = tmp19 + tmp20
      call gemv(state%s16, state%s43, tmp22, trans="t")
      grad_vn = tmp21 + tmp22
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp23 = 6.283185307179586_wp*state%s29
         call gemv(state%s11, state%s29, tmp24)
         tmp25 = -tmp24
         tmp26 = tmp23 + tmp25
         call gemv(state%s12, state%s29, tmp27)
         tmp28 = -tmp27
         tmp29 = tmp26 + tmp28
         tmp30 = -tmp29
         tmp31 = tmp5 + tmp30
         call gemv(state%s16, state%s28, tmp32)
         tmp33 = state%s15*tmp32
         call gemv(state%s18, state%s28, tmp34)
         tmp35 = state%s17*tmp34
         tmp36 = tmp33 + tmp35
         tmp37 = -tmp36
         tmp38 = tmp31 + tmp37
         call gemv(state%s11, state%s33, tmp39)
         tmp40 = state%s20*tmp39
         tmp41 = tmp38 + tmp40
         tmp42 = dot(state%s38, tmp41)
         tmp43 = state%s37(npt + 1:2*npt)
         tmp44 = tmp23 + tmp27
         tmp45 = -tmp44
         tmp46 = tmp45 + tmp34
         tmp47 = dot(tmp43, tmp46)
         tmp48 = tmp42 + tmp47
         tmp49 = state%s26*state%vn
         tmp50 = state%s25*state%s28
         tmp51 = tmp49 + tmp50
         call gemv(state%s18, tmp51, tmp52)
         tmp53 = 6.283185307179586_wp*state%s33
         call gemv(state%s12, state%s33, tmp54)
         tmp55 = -tmp54
         tmp56 = tmp53 + tmp55
         tmp57 = -tmp56
         tmp58 = tmp52 + tmp57
         tmp59 = dot(state%s40, tmp58)
         tmp60 = tmp48 + tmp59
         energy = energy + tmp60
      end if

      state%ready = 3
   end subroutine nonlocal_pcm_point_solve

   !> Nonlocal PCM (point charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs nonlocal_pcm_point_solve on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      real(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      real(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      real(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      real(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      real(wp), contiguous, intent(out) :: grad_a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp9(:), tmp10(:), &
                               tmp11(:), tmp12(:), tmp18(:), tmp24(:), tmp25(:), tmp26(:), &
                               tmp27(:), tmp28(:), tmp29(:), tmp30(:), tmp31(:), tmp32(:), &
                               tmp33(:), tmp244(:), tmp245(:), tmp246(:), tmp247(:), tmp248(:), &
                               tmp249(:), tmp250(:), tmp251(:), tmp252(:), tmp253(:), tmp254(:), &
                               tmp255(:), tmp256(:)
      real(wp) :: tmp6, tmp7, tmp8, tmp13, tmp14, tmp15, tmp16, tmp17, tmp19, tmp20, tmp21, tmp22, &
                  tmp23
      integer :: i, j

      if (state%matrix_free) then
         call nonlocal_pcm_point_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[nonlocal_pcm_point_weights] call nonlocal_pcm_point_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
