   end subroutine nonlocal_pcm_point_mf_assemble

   !> Nonlocal PCM (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs nonlocal_pcm_point_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[in] eps_inf  high-frequency permittivity of the solvent
   !> @param[in] lam  correlation length of the solvent polarization
   !> @param[in] eps_solute  relative permittivity inside the cavity
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_mf_medium(state, eps, eps_inf, lam, eps_solute, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> High-frequency permittivity of the solvent
      real(wp), intent(in) :: eps_inf
      !> Correlation length of the solvent polarization
      real(wp), intent(in) :: lam
      !> Relative permittivity inside the cavity
      real(wp), intent(in) :: eps_solute
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, &
                          "[nonlocal_pcm_point_mf_medium] call nonlocal_pcm_point_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => lam)
      end associate

      state%eps_inf = eps_inf
      state%eps = eps
      state%eps_solute = eps_solute
      state%op2%npt = 3*npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%a => state%a
      state%s7 = 1.0_wp/lam
      state%op2%c1 = state%s7
      state%s8 = 1.0_wp/state%eps_inf
      state%s9 = state%s8*state%eps
      state%s10 = sqrt(state%s9)
      state%op2%c2 = state%s10
      state%s13 = 1.0_wp/state%eps
      tmp1 = -state%s13
      state%s14 = state%s8 + tmp1
      state%s15 = state%eps_solute*state%s14
      state%op2%c3 = state%s15
      state%s17 = state%s8*state%eps_solute
      state%op2%c4 = state%s17
      state%s19 = state%s13*state%eps_inf
      state%op2%c5 = state%s19
      call state%solver%setup(state%op2, error)
      if (allocated(error)) return
      state%s20 = -state%s19
      state%s21 = 1.0_wp + state%s20
      state%s23 = -state%s15
      state%s25 = -state%s17
      state%s26 = 1.0_wp + state%s25
      state%s31 = 25.132741228718345_wp*state%eps_solute
      state%s32 = 1.0_wp/state%s31
      state%s34 = -state%s32
      state%s58 = lam**(-2)

      state%ready = 2
   end subroutine nonlocal_pcm_point_mf_medium

   !> Nonlocal PCM (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs nonlocal_pcm_point_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] u  interior potential trace, times 4 pi
   !> @param[out] q  interior normal-field trace, times 4 pi
   !> @param[out] w_ext  exterior auxiliary trace, times 4 pi
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_mf_solve(state, v, vn, energy, u, q, w_ext, grad_v, grad_vn, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
