      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Interior potential trace, times 4 pi
      real(wp), contiguous, intent(out) :: u(:)
      !> Interior normal-field trace, times 4 pi
      real(wp), contiguous, intent(out) :: q(:)
      !> Exterior auxiliary trace, times 4 pi
      real(wp), contiguous, intent(out) :: w_ext(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      real(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp4(:), tmp5(:), tmp6(:), tmp10(:), tmp11(:), &
                               tmp12(:), tmp16(:), tmp17(:), tmp18(:), tmp19(:), tmp20(:), &
                               tmp21(:), tmp84(:), tmp85(:), tmp86(:), tmp87(:), tmp88(:), &
                               tmp91(:), tmp93(:), tmp96(:), tmp97(:), tmp98(:), tmp99(:), &
                               tmp100(:), tmp101(:), tmp142(:), tmp143(:), tmp144(:), tmp145(:), &
                               tmp151(:), tmp181(:), tmp182(:), tmp183(:), tmp184(:), tmp185(:), &
                               tmp186(:), tmp213(:), tmp214(:), tmp215(:), tmp235(:), tmp236(:), &
                               tmp237(:), tmp238(:), tmp239(:), tmp280(:), tmp281(:), tmp283(:), &
                               tmp284(:), tmp285(:), tmp286(:), tmp289(:), tmp290(:), tmp291(:), &
                               tmp292(:), tmp293(:), tmp313(:), tmp314(:), tmp315(:), tmp345(:), &
                               tmp346(:), tmp347(:), tmp348(:)
      real(wp), allocatable :: tmp3(:), tmp89(:), tmp90(:)
      real(wp) :: tmp7, tmp8, tmp9, tmp13, tmp14, tmp15, tmp92, tmp94, tmp95, tmp146, tmp147, &
                  tmp148, tmp149, tmp150, tmp282, tmp287, tmp288, tmp349, tmp350
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, &
                          "[nonlocal_pcm_point_mf_solve] call nonlocal_pcm_point_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_mf_solve] vn: wrong shape")
         return
      end if
      if (any(shape(u) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_mf_solve] u: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(w_ext) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_mf_solve] w_ext: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_mf_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_mf_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
